mapper.select:

where transfer_id = #{transferId}
order by sort_order asc, detail_id asc
for update

mapper.update:
update inv_transfer_detail
set delivered_quantity = #{deliveredQuantity}
where detail_id = #{detailId}

update inv_transfer_detail
set delivered_quantity = delivered_quantity - #{deliveredQuantity}
where detail_id = #{detailId}
  and delivered_quantity >= #{deliveredQuantity}

update inv_transfer_detail
set received_quantity = #{receivedQuantity}
where detail_id = #{detailId}
